TRAINING_PAIRS = [('How many customers are there?', 'SELECT COUNT(*) AS total_customers FROM customers'), ('How many opportunities are in each stage?', 'SELECT stage, COUNT(*) AS deal_count FROM opportunities GROUP BY stage ORDER BY stage'), ('What is total won revenue?', "SELECT SUM(amount) AS won_revenue FROM opportunities WHERE stage = 'Won'"), ('Which region has the highest won revenue?', "SELECT c.region, SUM(o.amount) AS revenue FROM opportunities o JOIN customers c ON c.customer_id=o.customer_id WHERE o.stage='Won' GROUP BY c.region ORDER BY revenue DESC LIMIT 1"), ('What is the average deal value by stage?', 'SELECT stage, ROUND(AVG(amount),2) AS avg_amount FROM opportunities GROUP BY stage ORDER BY stage')]
